import React, { useState } from "react";
import { Link } from "react-router-dom";

function NavBar() {
  const [open, setOpne] = useState(false);
    
  const planets = [
    "Mercury",
    "Venus",
    "Earth",
    "Mars",
    "Jupiter",
    "Saturn",
    "Uranus",
    "Neptune",
  ];

  return (
    <>
      <div className="font-poppins bg-transparent text-white   w-full  top-0 left-0">
        <div className=" lg:flex  items-center justify-between lg:px-16">
          <div className=" items-start ">
            <Link to="/">
              Solar System
            </Link>
          </div>
          <p className=" absolute top-6 right-6 lg:hidden text-3xl" onClick={()=>{setOpne(!open);}}>
            {/* <img src="" alt="" srcset="" /> */}
            <img className={open} width="30" height="30" src="https://img.icons8.com/ios/50/FFFFFF/menu.png" alt="menu"/>
          <i class={!open?"bi bi-list":"bi bi-x"}></i>
          </p>
        <ul className={`lg:flex absolute lg:static md:mt-0 z-auto z[-1] lg:opacity-100 w-full
           p-4 md:p-0 md:w-auto md:pt-2 md:me-12  pl-10   ${open?"mt-0 opacity-100  transition-all duration-300 ease-in ":"mt-[-350px] opacity-0 "} `} >
            <Link>Home</Link>
           </ul>
        </div>
      </div>
    </>
  );
}

export default NavBar;
